sealed interface Tok {                          // token kinds; data classes carry payloads
    data class Name(val text: String, val pos: Int) : Tok; data object Plus : Tok
}
class Parser(private val toks: List<Tok>) { private var i = 0
    private fun peek(k: Int = 0) = toks[i + k]
    private fun expect(t: Tok): Tok = if (peek() == t) toks[i++] else error("expected $t at ${peek()}")
    fun expr(): Node {
        var left = term()
        while (peek() == Tok.Plus) { i++; left = Binary(left, term()) }   // loop, not left recursion
        return left
    }
}
